import sys
import numpy as np
import xarray as xr

TARGET_SNIPPETS = ('/xarray/core/', '/xarray/structure/')

stack = []
max_depth = 0


def in_target(filename: str) -> bool:
    return any(s in filename for s in TARGET_SNIPPETS)


def tracer(frame, event, arg):
    global max_depth
    if event not in ('call', 'return', 'exception'):
        return tracer

    filename = frame.f_code.co_filename
    if not in_target(filename):
        return tracer

    if event == 'call':
        stack.append(frame)
        if len(stack) > max_depth:
            max_depth = len(stack)
    elif event == 'return':
        if stack and stack[-1] is frame:
            stack.pop()
        else:
            # Keep stack consistent if tracing order differs.
            for i in range(len(stack) - 1, -1, -1):
                if stack[i] is frame:
                    del stack[i:]
                    break
    elif event == 'exception':
        # Depth unchanged, but event is included in traced stream.
        if len(stack) > max_depth:
            max_depth = len(stack)

    return tracer


a = xr.DataArray(
    np.array([[1.0, 2.0], [3.0, 4.0]], dtype=np.float64),
    dims=("time", "x"),
    coords={"time": [0, 1], "x": [10, 20]},
    name="a",
)
b = xr.DataArray(
    np.array([[5.0, 6.0], [7.0, 8.0]], dtype=np.float64),
    dims=("time", "x"),
    coords={"time": [1, 2], "x": [20, 30]},
    name="b",
)
c = xr.DataArray(
    np.array([[9.0, 10.0], [11.0, 12.0]], dtype=np.float64),
    dims=("time", "x"),
    coords={"time": [2, 3], "x": [30, 40]},
    name="c",
)

sys.settrace(tracer)
try:
    xr.align(a, b, c, join='outer', copy=False, fill_value=-999.0)
finally:
    sys.settrace(None)

print(max_depth)
